struct JointObservedActualStationSlopeV1 {bool valid=false,descent=false;int direction=0;double gradient=0,tolerance=0;std::size_t connected_blocks=0,dimensions=0;};
inline JointObservedActualStationSlopeV1 joint_observed_actual_station_slope_from_factors_v1(ceres::Problem&problem,double*x,int direction,const std::vector<ceres::ResidualBlockId>&connected,bool allow_numeric_held=false){
 JointObservedActualStationSlopeV1 out;out.direction=direction;out.connected_blocks=connected.size();out.valid=direction!=0&&problem.HasParameterBlock(x)&&(allow_numeric_held||!problem.IsParameterBlockConstant(x))&&problem.ParameterBlockSize(x)==1&&problem.GetManifold(x)==nullptr&&!connected.empty();double absolute_terms=0;
 for(auto rid:connected){if(!out.valid)break;std::vector<double*>params;problem.GetParameterBlocksForResidualBlock(rid,&params);const auto*cost=problem.GetCostFunctionForResidualBlock(rid);std::vector<const double*>values(params.begin(),params.end());std::vector<double*>jac(params.size(),nullptr);const auto station=std::find(params.begin(),params.end(),x);if(station==params.end()){out.valid=false;break;}const auto slot=std::size_t(station-params.begin());if(cost->parameter_block_sizes().at(slot)!=1){out.valid=false;break;}std::vector<double>residual(cost->num_residuals()),derivative(cost->num_residuals());jac[slot]=derivative.data();if(!cost->Evaluate(values.data(),residual.data(),jac.data())){out.valid=false;break;}double norm2=0;for(double v:residual){if(!std::isfinite(v)){out.valid=false;break;}norm2+=v*v;}double loss_derivative=1;if(const auto*loss=problem.GetLossFunctionForResidualBlock(rid)){double rho[3];loss->Evaluate(norm2,rho);loss_derivative=rho[1];}if(!std::isfinite(loss_derivative)||loss_derivative<0){out.valid=false;break;}for(std::size_t j=0;j<residual.size();++j){const double v=loss_derivative*residual[j]*derivative[j];if(!std::isfinite(v)){out.valid=false;break;}out.gradient+=v;absolute_terms+=std::abs(v);}out.dimensions+=residual.size();}
 out.tolerance=128*std::numeric_limits<double>::epsilon()*std::max(1.,absolute_terms);out.valid=out.valid&&std::isfinite(out.gradient)&&std::isfinite(out.tolerance);out.descent=out.valid&&direction*out.gradient < -out.tolerance;return out;
}
// Current dynamic graphs enable Ceres' removal incidence index. These queries
// visit only connected factors, including full W/loss and row constraints.
inline JointObservedActualStationSlopeV1 joint_observed_actual_station_slope_v1(ceres::Problem&problem,double*x,int direction,bool removal_incidence_enabled,bool allow_numeric_held=false){
 if(!removal_incidence_enabled)throw std::runtime_error("live cell KKT requires the existing Ceres residual incidence index");std::vector<ceres::ResidualBlockId>connected;if(problem.HasParameterBlock(x))problem.GetResidualBlocksForParameterBlock(x,&connected);return joint_observed_actual_station_slope_from_factors_v1(problem,x,direction,connected,allow_numeric_held);
}
inline bool joint_observed_cell_release_allowed_v1(const JointObservedActualStationSlopeV1&current,const JointObservedActualStationSlopeV1&neighbor){return current.valid&&!current.descent&&neighbor.valid&&neighbor.descent;}
