struct Hash {std::uint64_t h=1469598103934665603ull;void bytes(const void*p,std::size_t n){const auto*b=static_cast<const unsigned char*>(p);for(std::size_t i=0;i<n;++i){h^=b[i];h*=1099511628211ull;}}template<class T>void scalar(const T&v){bytes(&v,sizeof(v));}void text(const std::string&s){scalar(s.size());bytes(s.data(),s.size());}std::string value()const{return std::to_string(h);}};
inline std::string source_contract_token(const JointPacket&p){
 Hash h;h.text(p.source_hash);h.scalar(p.rows.size());
 const bool current=p.source_json.contains("runtime_current_input_v1");
 if(current){const auto&v=p.source_json.at("runtime_current_input_v1");if(v.at("version")!=1||v.at("raw_rows").get<std::size_t>()!=p.rows.size())throw std::runtime_error("branch current-input immutable binding/count mismatch");const auto sha=v.at("binding").at("sha256").get<std::string>();if(sha.size()!=64)throw std::runtime_error("branch current-input binding SHA missing");h.text("issued_current_input_binding_v1");h.text(sha);h.text(v.at("logical_source_id").get<std::string>());for(const char*k:{"raw_rows","physical_rows","training_rows","fit_rows","inspection_rows"})h.scalar(v.at(k).get<std::size_t>());}
 for(const auto&r:p.rows){
  // Current-input binding authenticates the unmaterialized source identities,
  // complete Query and allowed-path tables. Never hash an inactive empty shell
  // as if it represented those original definitions.
  h.scalar(r.active);h.scalar(r.material);h.scalar(r.kind);h.scalar(r.pts);h.scalar(r.uv);h.scalar(r.normal);h.scalar(r.E);h.scalar(r.width_block);h.scalar(r.width_sign);h.scalar(r.stroke_pair_index);h.scalar(r.stroke_source_side);
  if(current&&!r.active)continue;
  h.text(r.source_dataset_id);h.text(r.source_row_id);h.text(r.source_group_id);h.text(r.shot_id);h.text(r.fit_role);h.scalar(r.source_print_identity_reviewed);h.scalar(r.station_domain_path);h.scalar(r.source_station_intervals.size());for(const auto&v:r.source_station_intervals)h.scalar(v);h.scalar(r.numerical_continuous_board_intervals.size());for(const auto&v:r.numerical_continuous_board_intervals)h.scalar(v);h.scalar(bool(r.source_finite_paths));if(r.source_finite_paths){h.scalar(r.source_finite_paths->size());for(int pi:*r.source_finite_paths)h.scalar(pi);}const auto*q=r.query.get();h.scalar(q);if(q){h.scalar(q->origin);h.scalar(q->scale);for(const auto*v:{&q->alpha,&q->nx,&q->ny,&q->den}){h.scalar(v->size());for(double x:*v)h.scalar(x);}h.scalar(q->uv.size());for(const auto&v:q->uv)h.scalar(v);}
 }
 // W and source grouping are immutable inputs, independent of chosen chart.
 for(const auto&g:p.groups){h.text(g.id);h.text(g.statistic_kind);h.scalar(g.rank);h.scalar(g.rows.size());for(auto i:g.rows)h.scalar(i);h.scalar(g.W.size());for(double w:g.W)h.scalar(w);}return h.value();
}
template<class Builder>inline std::string aux_token(const Builder&b){Hash h;h.scalar(b.core.packet.rows.size());for(std::size_t i=0;i<b.core.packet.rows.size();++i){const auto&r=b.core.packet.rows[i];h.scalar(r.path);h.scalar(r.numerical_shape_segment);h.scalar(r.station);h.scalar(r.row);h.scalar(r.alpha);h.scalar(b.core.station.at(i));h.scalar(b.core.row.at(i));h.scalar(b.core.alpha.at(i));}return h.value();}
inline std::string ledger_token(const eventio::Json&ledger){const auto text=ledger.dump();eventio::FastSHA256Stream h;h.update(reinterpret_cast<const std::uint8_t*>(text.data()),text.size());return h.finish();}
