inline bool joint_observed_branch_transaction_acceptance_v1(const JointObservedBranchPlanV1&p,double before,double candidate,const eventio::Json&old_debt,const eventio::Json&new_debt,const eventio::Json&proof){
 if(!std::isfinite(before)||!std::isfinite(candidate)||!joint_observed_branch_debt_nonworsened_v1(old_debt,new_debt))return false;std::size_t pure=0;for(const auto&c:p.rows)pure+=c.pure_same_vertex_cell_change;if(pure&&(proof.is_null()||proof.value("schema",std::string{})!="rinkfit.actual_same_vertex_cell_inward_descent.v1"||proof.value("requested_cell_changes",std::size_t(0))!=pure||!proof.value("all_changed_cells_have_actual_complete_inward_descent",false)))return false;
 if(candidate<before)return true;
 // At an exact shared vertex the same physical point has equal cost. Release
 // its old one-sided box only with a strict derivative on the new actual graph.
 return pure&&!p.rows.empty()&&pure==p.rows.size()&&std::abs(candidate-before)<=128*std::numeric_limits<double>::epsilon()*std::max(1.,std::abs(before));
}
